@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.fade-in {
  animation: fadeIn 0.4s ease-out forwards;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@supports (view-transition-name: none) {
  @media (prefers-reduced-motion: no-preference) {
    html[data-transition-direction="forward"]::view-transition-old(root) {
      animation: slideOutLeft 0.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
    }

    html[data-transition-direction="forward"]::view-transition-new(root) {
      animation: slideInRight 0.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
    }

    html[data-transition-direction="backward"]::view-transition-old(root) {
      animation: slideOutRight 0.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
    }

    html[data-transition-direction="backward"]::view-transition-new(root) {
      animation: slideInLeft 0.5s cubic-bezier(0.4, 0, 0.2, 1) forwards;
    }
  }
}

@keyframes slideOutLeft {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-30%);
    opacity: 0;
  }
}

@keyframes slideInRight {
  from {
    transform: translateX(30%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes slideOutRight {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(30%);
    opacity: 0;
  }
}

@keyframes slideInLeft {
  from {
    transform: translateX(-30%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fade-in {
    animation: none;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

